<?php $pageTitle = 'Manage offerings'; $packageItemsById = []; foreach ($packageItems as $link) $packageItemsById[(int) $link['package_id']][] = (int) $link['menu_item_id']; ?>
<section class="page-intro"><div class="intro-inner"><span class="eyebrow">Administrator tools</span><h1>Manage menu and packages.</h1><p>Update customer-facing names, descriptions, PHP prices, minimums, package choices, and offering availability. Existing reservations retain their saved prices and selections.</p></div></section><section class="content-section"><div class="operations-nav"><a class="button button-secondary" href="<?= rc_url('owner') ?>">← Operations</a></div><section class="surface"><div class="surface-heading"><h2>Food selections</h2><span><?= count($items) ?> records</span></div><?php if ($items): ?><div class="table-wrap"><table><thead><tr><th>Food item</th><th>Category</th><th>Price</th><th>Availability</th><th>Edit</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= rc_e($item['name']) ?><small><?= rc_e($item['description']) ?></small></td><td><?= rc_e($item['category']) ?></td><td><?= rc_money(rc_cents($item['price'])) ?></td><td><form method="post" action="<?= rc_e(rc_endpoint()) ?>" data-confirm="Change customer availability for <?= rc_e($item['name']) ?>?"><?= rc_csrf_field() ?><input type="hidden" name="action" value="toggle-item"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="text-link" type="submit"><?= $item['is_active'] ? 'Active · Deactivate' : 'Inactive · Activate' ?></button></form></td><td><details class="edit-details"><summary>Edit item</summary><form method="post" action="<?= rc_e(rc_endpoint()) ?>" class="form-stack"><?= rc_csrf_field() ?><input type="hidden" name="action" value="update-item"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><label>Name<input name="name" maxlength="255" value="<?= rc_e($item['name']) ?>" required></label><label>Category<input name="category" maxlength="50" value="<?= rc_e($item['category']) ?>" required></label><label>Description<textarea name="description" maxlength="5000"><?= rc_e($item['description']) ?></textarea></label><label>Price PHP<input name="price" type="number" min="0.01" step="0.01" value="<?= rc_e($item['price']) ?>" required></label><label><input type="checkbox" name="is_vegan" <?= $item['is_vegan'] ? 'checked' : '' ?>> Vegan</label><label><input type="checkbox" name="is_gluten_free" <?= $item['is_gluten_free'] ? 'checked' : '' ?>> Gluten-free</label><button class="button button-secondary" type="submit">Save item</button></form></details></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No menu items yet. Add the initial selections from Operations.</p><?php endif; ?></section>
<section class="surface"><div class="surface-heading"><h2>Catering packages</h2><span><?= count($packages) ?> records</span></div><?php if ($packages): ?><div class="table-wrap"><table><thead><tr><th>Package</th><th>Current price</th><th>Minimum</th><th>Availability</th><th>Edit</th></tr></thead><tbody><?php foreach ($packages as $package): ?><tr><td><?= rc_e($package['package_name']) ?><small><?= rc_e($package['description']) ?></small></td><td><?= rc_money(rc_cents($package['package_price'])) ?> <?= $package['price_type'] === 'Per Person' ? '/ person' : 'fixed' ?></td><td><?= (int) $package['minimum_guests'] ?></td><td><form method="post" action="<?= rc_e(rc_endpoint()) ?>" data-confirm="Change customer availability for <?= rc_e($package['package_name']) ?>?"><?= rc_csrf_field() ?><input type="hidden" name="action" value="toggle-package"><input type="hidden" name="id" value="<?= (int) $package['package_id'] ?>"><button class="text-link" type="submit"><?= rc_e($package['status']) ?> · Toggle</button></form></td><td><details class="edit-details"><summary>Edit package</summary><form method="post" action="<?= rc_e(rc_endpoint()) ?>" class="form-stack"><?= rc_csrf_field() ?><input type="hidden" name="action" value="update-package"><input type="hidden" name="id" value="<?= (int) $package['package_id'] ?>"><label>Package name<input name="package_name" maxlength="160" value="<?= rc_e($package['package_name']) ?>" required></label><label>Description<textarea name="description" maxlength="5000"><?= rc_e($package['description']) ?></textarea></label><label>Price type<select name="price_type"><option <?= $package['price_type'] === 'Fixed' ? 'selected' : '' ?>>Fixed</option><option <?= $package['price_type'] === 'Per Person' ? 'selected' : '' ?>>Per Person</option></select></label><label>Price PHP<input name="package_price" type="number" min="0.01" step="0.01" value="<?= rc_e($package['package_price']) ?>" required></label><label>Minimum guests<input name="minimum_guests" type="number" min="1" value="<?= (int) $package['minimum_guests'] ?>" required></label><fieldset><legend>Permitted choices · select one</legend><div class="option-grid"><?php foreach ($items as $item): if (!$item['is_active']) continue; ?><label class="option-choice"><input type="checkbox" name="menu_items[]" value="<?= (int) $item['id'] ?>" <?= in_array((int) $item['id'], $packageItemsById[(int) $package['package_id']] ?? [], true) ? 'checked' : '' ?>><span><strong><?= rc_e($item['name']) ?></strong><small><?= rc_e($item['category']) ?></small></span></label><?php endforeach; ?></div></fieldset><button class="button button-secondary" type="submit">Save package</button></form></details></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No catering packages yet. Add packages from Operations.</p><?php endif; ?></section></section>
